  function stripHtml(html){const d=document.createElement("div");d.innerHTML=html;return d.textContent.replace(/\s+/g," ").trim();}
  function safeName(s){return normalize(s).replace(/\s+/g,"-")||"semitic-atlas";}
  function normalizeForSpeech(text){return String(text||"").replace(/\*/g,"").replace(/[𐤀-𐥿𐡀-𐡿𐩠-𐩿𐎀-𐎿𒀀-𒿿]/gu," ").replace(/š/g,"ش").replace(/ś/g,"س").replace(/ṣ́/g,"ض").replace(/ṣ/g,"ص").replace(/ṭ/g,"ط").replace(/ḍ/g,"ض").replace(/ḥ/g,"ح").replace(/ḫ/g,"خ").replace(/ġ/g,"غ").replace(/ʿ/g,"ع").replace(/[ʾʔ]/g,"ء").replace(/ṯ/g,"ث").replace(/ḏ/g,"ذ").replace(/ā/g,"ا").replace(/ē/g,"ي").replace(/ī/g,"ي").replace(/ō/g,"و").replace(/ū/g,"و").replace(/q/g,"ق").replace(/k/g,"ك").replace(/g/g,"ج").replace(/b/g,"ب").replace(/t/g,"ت").replace(/d/g,"د").replace(/r/g,"ر").replace(/m/g,"م").replace(/n/g,"ن").replace(/l/g,"ل").replace(/w/g,"و").replace(/y/g,"ي").replace(/h/g,"ه").replace(/f/g,"ف").replace(/p/g,"پ").replace(/s/g,"س").replace(/z/g,"ز").replace(/[\-_]+/g," ").replace(/\s+/g," ").trim();}
  let ttsProbeResult=null;
  function ttsVoicesReady(){return "speechSynthesis" in window && speechSynthesis.getVoices().length>0;}
  function waitForVoices(timeoutMs){
    return new Promise(resolve=>{
      if(!("speechSynthesis" in window)){resolve(false);return;}
      if(speechSynthesis.getVoices().length>0){resolve(true);return;}
      let done=false;
      const finish=ok=>{if(done)return;done=true;speechSynthesis.onvoiceschanged=null;resolve(ok);};
      speechSynthesis.onvoiceschanged=()=>finish(speechSynthesis.getVoices().length>0);
      speechSynthesis.getVoices();
      setTimeout(()=>finish(speechSynthesis.getVoices().length>0),timeoutMs||900);
    });
  }
  async function checkTTSSupport(){
    if(window.SemiticNative?.speak){ttsProbeResult="native";return "native";}
    if(!("speechSynthesis" in window)){ttsProbeResult="unsupported";return "unsupported";}
    const ok=await waitForVoices(900);
    ttsProbeResult=ok?"browser":"no-voices";
    return ttsProbeResult;
  }
  function ttsUnavailableMessage(status){
    if(status==="unsupported")return L("قراءة النطق غير مدعومة داخل واجهة هذا التطبيق. جرّب فتح نفس الصفحة في متصفح مثل Chrome، أو فعّل جسر الصوت الأصلي من إعدادات WebIntoApp.","Speech playback is not supported inside this app's webview. Try opening the page in a browser like Chrome, or enable the native audio bridge in WebIntoApp settings.");
    return L("لا توجد أصوات نطق مثبتة على الجهاز. افتح إعدادات Android ← إدارة عام ← تحويل النص إلى كلام، وثبّت محرك مثل \"خدمة تحويل النص لكلام من Google\" ثم أعد المحاولة.","No text-to-speech voices are installed on this device. Open Android Settings → General management → Text-to-speech, install an engine such as \"Google Text-to-Speech\", then try again.");
  }
  async function speak(text,rate=1,locale="ar-SA"){
    const spoken=/[A-Za-zāēīōūḥḫġʿʾšśṣṭḍṯḏ]/.test(String(text))?normalizeForSpeech(text):String(text);
    if(window.SemiticNative?.speak){window.SemiticNative.speak(spoken,rate,locale);return;}
    if(!("speechSynthesis" in window)){toast(ttsUnavailableMessage("unsupported"));return;}
    const ready=await waitForVoices(900);
    if(!ready){toast(ttsUnavailableMessage("no-voices"));return;}
    speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(spoken);
    u.rate=rate;u.pitch=.92;u.lang=locale;
    u.onerror=()=>toast(ttsUnavailableMessage("no-voices"));
    speechSynthesis.speak(u);
  }
  function stopSpeech(){if(window.SemiticNative?.stopSpeaking)window.SemiticNative.stopSpeaking();if("speechSynthesis" in window)speechSynthesis.cancel();}
  function nativePrint(title){if(window.SemiticNative?.printPage)window.SemiticNative.printPage(title);else window.print();}
  function openUrl(url){if(!url||!/^https:\/\//.test(url)){toast("رابط غير صالح");return;}window.open(url,"_blank","noopener");}
  async function copyText(text){try{await navigator.clipboard.writeText(text);toast(L("تم النسخ","Copied"));}catch(_){const ta=document.createElement("textarea");ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand("copy");ta.remove();toast(L("تم النسخ","Copied"));}}
  function downloadText(filename,text,mime="text/plain"){
    if(window.SemiticNative?.saveBase64){
      const encoded=btoa(unescape(encodeURIComponent(text)));
      window.SemiticNative.saveBase64(encoded,filename,mime);
      return;
    }
    try {
      const blob=new Blob([text],{type:`${mime};charset=utf-8`});
      const url=URL.createObjectURL(blob);
      const a=document.createElement("a");
      a.href=url;a.download=filename;a.rel="noopener";
      document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(url),3000);
      toast(L("بدأ تنزيل الملف","File download started"));
    } catch (_) {
      const encoded=btoa(unescape(encodeURIComponent(text)));
      const a=document.createElement("a");a.href=`data:${mime};base64,${encoded}`;a.download=filename;a.click();
    }
  }
