  function openArtifactAnnotation(id){const a=D.artifacts.find(x=>x.id===id);if(!a)return;openModal(`<span class="badge gold">${L(a.title,a.en)}</span><h2>${L("تعليق على السجل الأثري","Artifact record annotation")}</h2><input class="input" id="modalAnnotationQuote" style="width:100%" value="${escapeHtml(a.corpus||a.title)}"><textarea class="textarea workspace-note" id="modalAnnotationBody" placeholder="${L("ملاحظة على القراءة أو البيانات أو الحقوق...","Note on reading, metadata or rights...")}"></textarea><select class="select" id="modalAnnotationType"><option value="comment">${L("تعليق","Comment")}</option><option value="correction">${L("تصحيح مقترح","Suggested correction")}</option><option value="source">${L("إحالة مصدر","Source link")}</option></select><button class="button primary" data-action="save-artifact-annotation" data-artifact="${a.id}" style="margin-top:12px">${L("حفظ وربط بالقطعة","Save & link to artifact")}</button>`);}
  function addAnnotation(target,quote,body,type){if(!body&&!quote){toast(L("اكتب تعليقًا أو نصًا محددًا","Add a comment or quoted text"));return false;}state.annotations=state.annotations||{};state.annotations[`ann:${Date.now()}`]={target,quote,body,type,date:today,author:"سوسن علي عبدالله الحضوري"};saveState();return true;}
