  function openCaseStudy(id){const c=D.caseStudies.find(x=>x.id===id);if(!c)return;openModal(`<span class="badge gold">${L(branch(c.branch).ar,branch(c.branch).en)}</span><h2>${c.title}</h2><div class="academic-note"><strong>${L("مشكلة البحث","Research problem")}:</strong> ${c.question}</div><h3>${L("سير التحقيق","Investigation workflow")}</h3><ol>${c.steps.map((s,i)=>`<li><strong>${i+1}.</strong> ${s}</li>`).join("")}</ol><h3>${L("المخرجات المطلوبة","Required outputs")}</h3><div class="meta-list">${c.outputs.map(o=>`<span class="badge">${o}</span>`).join("")}</div><textarea class="textarea workspace-note" id="caseWorksheet" placeholder="${L("سجّل الفرضيات والشواهد والمراجع ودرجة اليقين...","Record hypotheses, evidence, references and confidence...")}"></textarea><button class="button secondary" data-action="save-case-note" data-case="${c.id}">${L("حفظ كورقة بحث","Save as research note")}</button>`);}
  function exportProgressReport(){const rows=D.languages.map(x=>`${x.ar},${x.en},${completionFor(x.id)}%,${Object.keys(state.completed).filter(k=>k.startsWith(`${x.id}:`)&&state.completed[k]).length}`).join("\n");downloadText(`reading-progress-${today}.csv`,`اللغة,Language,Progress,Completed chapters\n${rows}`,"text/csv");}
  function languageStatsRows(){return Object.entries(D.branch).map(([id,b])=>{const list=D.languages.filter(x=>x.branch===id);return [b.ar,b.en,list.length,list.filter(x=>/منقرض/.test(x.status)).length,new Set(list.map(x=>x.script)).size,list.reduce((n,x)=>n+x.evidence.length,0)];});}
  function exportLanguageStatistics(){downloadText(`language-statistics-${today}.csv`,`الفرع,Branch,Languages,Marked extinct,Script labels,Evidence labels\n${languageStatsRows().map(r=>r.map(csvCell).join(",")).join("\n")}`,"text/csv");}
  function csvCell(value){const s=String(value??"");return /[",\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
  function toggleReviewItem(index){const key=chapterKey(lang().id,state.selectedChapter);state.reviews[key]=state.reviews[key]||{};state.reviews[key][index]=!state.reviews[key][index];state.reviews[key].updated=today;saveState();render();}
  function saveReviewDecision(){const key=chapterKey(lang().id,state.selectedChapter);state.reviews[key]=state.reviews[key]||{};state.reviews[key].decision=$("#reviewDecision")?.value||"draft";state.reviews[key].comment=$("#reviewComment")?.value.trim()||"";state.reviews[key].updated=today;saveState();toast(L("تم حفظ قرار المراجعة","Review decision saved"));}
  function exportAcademicReview(){const key=chapterKey(lang().id,state.selectedChapter),review=state.reviews[key]||{};const text=`# تقرير المراجعة الأكاديمية\n\n- اللغة: ${lang().ar}\n- الفصل: ${state.selectedChapter} — ${getChapter(lang(),state.selectedChapter).titleAr}\n- التاريخ: ${today}\n- القرار: ${review.decision||"draft"}\n\n## قائمة الفحص\n${reviewCriteria.map((c,i)=>`- [${review[i]?"x":" "}] ${c}`).join("\n")}\n\n## تعليق المراجع\n${review.comment||"—"}`;downloadText(`academic-review-${lang().id}-${state.selectedChapter}.md`,text,"text/markdown");}
  function runProofread(){const text=$("#proofreadInput")?.value||"";state.proofreadText=text;const issues=[];if(/ {2,}/.test(text))issues.push(L("توجد مسافات متكررة.","Repeated spaces detected."));if(/ـ{2,}/.test(text))issues.push(L("توجد مطّات زخرفية قد تعيق البحث والفهرسة.","Decorative tatweel may impair search and indexing."));if(/[أإآ]/.test(text)&&/\bا[\p{L}]+/u.test(text))issues.push(L("راجع اتساق كتابة الهمزات؛ لا يوصى بالتوحيد الآلي داخل الاقتباسات.","Review hamza consistency; do not normalize quotations automatically."));if(!/[.!؟?؛:]\s*$/.test(text.trim())&&text.trim())issues.push(L("قد تحتاج الفقرة إلى علامة ترقيم ختامية.","The paragraph may need terminal punctuation."));if(text.length>600&&!/\(|\[|مرجع|المصدر|KAI|DASI|OCIANA/i.test(text))issues.push(L("النص طويل ولا تظهر فيه إحالة واضحة؛ راجع التوثيق.","Long text has no visible citation marker; review sourcing."));if(/\*[^\s]+/.test(text))issues.push(L("وُجدت صيغة بنجمة؛ تأكد من وصفها بأنها معاد بناؤها.","A starred form was found; label it explicitly as reconstructed."));const words=normalize(text).split(" ").filter(Boolean),duplicates=words.filter((w,i)=>w.length>3&&w===words[i-1]);if(duplicates.length)issues.push(`${L("تكرار متجاور محتمل","Possible adjacent repetition")}: ${[...new Set(duplicates)].join("، ")}`);state.proofreadResult=`<div class="metric-card"><span class="metric-icon">${issues.length}</span><div><strong>${issues.length?L("ملاحظات تحتاج مراجعة","items to review"):L("لم تُرصد مشكلات شكلية","No formal issues detected")}</strong><span>${text.length} ${L("حرفًا","characters")}</span></div></div>${issues.length?`<ol>${issues.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ol>`:`<div class="academic-note">${L("لا تزال المراجعة البشرية للمحتوى والمراجع مطلوبة.","Human content and source review is still required.")}</div>`}`;saveState();render();}
  function exportPayload(scope){if(scope==="current")return {language:lang(),chapter:getChapter(lang(),state.selectedChapter),content:stripHtml(chapterContent(lang(),state.selectedChapter)),citations:referencesFor(lang(),state.selectedChapter)};if(scope==="lexicon")return D.lexicon;if(scope==="inscriptions")return D.artifacts.filter(a=>a.category==="inscription");if(scope==="progress")return {completed:state.completed,bookmarks:state.bookmarks,notes:state.notes,annotations:state.annotations,reviews:state.reviews};return {version:D.datasetVersion||"1.0.0",languages:D.languages,sites:D.sites,artifacts:D.artifacts,lexicon:D.lexicon,references:D.references,soundLaws:D.soundLaws};}
  function advancedExport(){const scope=$("#exportScope")?.value||"current",format=$("#exportFormat")?.value||"markdown",payload=exportPayload(scope);let content="",ext=format,mime="text/plain";if(format==="json"){content=JSON.stringify(payload,null,2);mime="application/json";}else if(format==="csv"){const list=Array.isArray(payload)?payload:[payload];const keys=[...new Set(list.flatMap(x=>Object.keys(x)))];content=keys.join(",")+"\n"+list.map(x=>keys.map(k=>csvCell(typeof x[k]==="object"?JSON.stringify(x[k]):x[k])).join(",")).join("\n");mime="text/csv";}else if(format==="tei"){content=`<?xml version="1.0" encoding="UTF-8"?>\n<TEI xmlns="http://www.tei-c.org/ns/1.0"><teiHeader><fileDesc><titleStmt><title>Semitic Atlas Export</title><author>سوسن علي عبدالله الحضوري</author></titleStmt><publicationStmt><p>جامعة صنعاء — 2026</p></publicationStmt><sourceDesc><p>Local encyclopedia export; verify corpus records before citation.</p></sourceDesc></fileDesc></teiHeader><text><body><p>${escapeXml(JSON.stringify(payload))}</p></body></text></TEI>`;ext="xml";mime="application/xml";}else if(format==="latex"){content=`\\documentclass[14pt,a4paper]{extarticle}\n\\usepackage[arabic,bidi=default]{babel}\n\\usepackage{fontspec}\n\\setmainfont{Noto Naskh Arabic}\n\\begin{document}\n\\section*{تصدير بحثي من أطلس اللغات السامية}\n\\begin{verbatim}\n${JSON.stringify(payload,null,2).slice(0,60000)}\n\\end{verbatim}\n\\end{document}`;ext="tex";mime="application/x-tex";}else{content=`# تصدير بحثي — ${scope}\n\nالتاريخ: ${today}\n\n\`\`\`json\n${JSON.stringify(payload,null,2)}\n\`\`\``;ext="md";mime="text/markdown";}downloadText(`semitic-atlas-${scope}-${today}.${ext}`,content,mime);}
  function escapeXml(value){return String(value).replace(/[<>&'"]/g,c=>({"<":"&lt;",">":"&gt;","&":"&amp;","'":"&apos;",'"':"&quot;"}[c]));}
  function exportStudyReport(){const x=lang(),n=state.selectedChapter,c=getChapter(x,n),refs=referencesFor(x,n);const text=`# تقرير دراسي: ${c.titleAr}\n\n**اللغة:** ${x.ar}  \n**الفصل:** ${n}/50  \n**التاريخ:** ${today}\n\n## أهداف التعلم\n- تحديد نوع الدليل وسياقه.\n- تحليل السمة الفيلولوجية ودرجة اليقين.\n- مقارنة المراسلات السامية المنتظمة.\n\n## المادة\n${stripHtml(chapterContent(x,n))}\n\n## أسئلة تطبيقية\n1. ما أقدم شاهد مؤرخ؟\n2. ما القراءة البديلة؟\n3. ما أثر نظام الكتابة في التحليل؟\n\n## المراجع\n${refs.map(r=>`- ${cite(r)}`).join("\n")}`;downloadText(`study-report-${x.id}-${n}.md`,text,"text/markdown");}
  function generateSmartCitation(){const x=D.languages.find(l=>l.id===$("#citationLanguage")?.value)||lang(),n=Math.max(1,Math.min(50,Number($("#citationChapter")?.value||state.selectedChapter))),style=$("#smartCitationStyle")?.value||"apa";state.citations.style=style;saveState();const out=$("#smartCitationOutput");if(out)out.textContent=chapterCitation(x,n,style);}
