  function openSpecialStudy(index){const s=D.specializedStudies[index];if(!s)return;openModal(`<span class="badge gold">${L(branch(s.branch).ar,branch(s.branch).en)}</span><h2>${s.title}</h2><p>${s.scope}</p><h3>${L("بنية الدراسة المقترحة","Proposed study structure")}</h3><ol><li>${L("تعريف corpus وحدود الفترة والمنطقة.","Define corpus, period and region.")}</li><li>${L("إنشاء جدول الشواهد والقراءات والمراجع.","Build an evidence, reading and bibliography table.")}</li><li>${L("تحليل الصوتيات والصرف والمعجم في سياق النوع النصي.","Analyze phonology, morphology and lexicon by genre.")}</li><li>${L("ربط النتائج بالأطلس والمواد الأثرية.","Link results to atlas and archaeological records.")}</li><li>${L("عرض الخلاف العلمي ودرجة اليقين.","State scholarly alternatives and confidence.")}</li></ol><button class="button secondary" data-action="export-special-study" data-index="${index}">⇩ ${L("تصدير الخطة","Export plan")}</button>`);}
  function exportDossier(){const list=D.artifacts.filter(a=>state.mediaFilter==="all"||a.category===state.mediaFilter);const text=`# حقيبة تعليمية: أطلس اللغات السامية\n\nإعداد الطالبة: سوسن علي عبدالله الحضوري\nإشراف: الأستاذ الدكتور أحمد فقعس\nالتاريخ: ${today}\n\n${list.map((a,i)=>`## ${i+1}. ${a.title}\n- التاريخ: ${a.date}\n- المكان: ${a.place}\n- الحفظ: ${a.museum}\n- الخامة: ${a.material}\n- الخط: ${a.script}\n- الحقوق: ${a.license}\n- المصدر: ${a.source||"إنشاء تعليمي أصلي"}\n\nأسئلة: ما نوع الدليل؟ ما درجة اليقين؟ ما المعلومات اللازمة قبل الاستشهاد؟`).join("\n\n")}`;downloadText("semitic-atlas-educational-dossier.md",text,"text/markdown");}
  function playLexiconSequence(){const e=D.lexicon[0];speak(Object.values(e.forms).filter(x=>x&&x!=="—").join(". "),.75,"ar-SA");}
  function showGraphNode(root){const e=D.lexicon.find(x=>x.root===root);if(!e){toast("Proto-Semitic root network");return;}openModal(`<span class="badge gold">${e.root}</span><h2>${e.meaning}</h2><div class="language-script">${e.proto}</div><p>${e.note}</p><div class="interactive-table"><table>${Object.entries(e.forms).map(r=>`<tr><th>${r[0]}</th><td>${r[1]}</td><td><button class="icon-button" data-action="speak-word" data-word="${escapeHtml(r[1])}">▶</button></td></tr>`).join("")}</table></div>`);}
  function exportComparison(){const a=D.languages.find(x=>x.id===state.compareA),b=D.languages.find(x=>x.id===state.compareB);const rows=compareRows(a,b);downloadText(`${a.id}-vs-${b.id}.md`,`# ${a.ar} × ${b.ar}\n\n${rows.map(r=>`## ${stripHtml(r[0])}\n- ${a.ar}: ${stripHtml(r[1])}\n- ${b.ar}: ${stripHtml(r[2])}\n- التحليل: ${stripHtml(r[3])}`).join("\n\n")}\n\n## المراجع\n${referencesFor(a,state.compareChapter).concat(referencesFor(b,state.compareChapter)).filter((v,i,arr)=>arr.findIndex(x=>x.id===v.id)===i).map(r=>`- ${cite(r)}`).join("\n")}`,"text/markdown");}
  function playPhoneme(p){const map={"ʾ":"أَ","h":"هَ","ḥ":"حَ","ʿ":"عَ","ḫ/x":"خَ","ġ/ɣ":"غَ","q":"قَ","k":"كَ","g":"جَ","ṭ":"طَ","ṣ":"صَ","ḍ/ṣ́":"ضَ","t":"تَ","d":"دَ","ṯ":"ثَ","ḏ":"ذَ","s":"سَ","š":"شَ","ś":"شَ","z":"زَ","r":"رَ","l":"لَ","m":"مَ","n":"نَ","b":"بَ","p":"پَ","w":"وَ","y":"يَ"};speak(map[p]||p,.65,"ar-SA");}
  function analyzeWord(){const w=$("#phoneticWord")?.value.trim()||"";const vowels=(w.match(/[aeiouāēīōū]/gi)||[]).length;$("#phoneticAnalysis").innerHTML=`<div class="academic-note"><strong>${escapeHtml(w)}</strong><br>${L("تقدير المقاطع","Estimated syllables")}: ${Math.max(1,vowels)}<br>${L("نمط أولي","Initial pattern")}: ${escapeHtml(w.replace(/[aeiouāēīōū]/gi,"V").replace(/[^V\s]/gi,"C"))}<br><small>${L("هذا محلل تعليمي شكلي؛ التحليل الدقيق يعتمد اللغة وقواعدها.","This is a formal teaching estimate; precise analysis is language-specific.")}</small></div>`;}
  function applySoundLaws(){const input=$("#reconstructionInput")?.value.trim()||"",target=$("#reconstructionTarget")?.value||"Canaanite";if(!input){toast(L("أدخل صيغة لإعادة البناء","Enter a reconstructed form"));return;}let form=input,steps=[{form,label:"Proto-Semitic",law:L("صيغة الإدخال","Input form")}];const laws=(D.soundLaws||[]).filter(l=>l.targets.includes(target));laws.forEach(l=>{let next=form;if(l.id==="canaanite-a-o")next=next.replace(/ā/g,"ō");else if(l.id==="arabic-p-f")next=next.replace(/p/g,"f");else if(l.id==="akkadian-th-s")next=next.replace(/ṯ/g,"š");else if(l.id==="akkadian-w-loss")next=next.replace(/yaw/g,"ū").replace(/aw/g,"ū");else if(l.id==="aramaic-th-t")next=next.replace(/ṯ/g,"t");else if(l.id==="diphthong-ay")next=next.replace(/ay/g,"ē");else if(l.id==="diphthong-aw")next=next.replace(/aw/g,"ō");if(next!==form){form=next;steps.push({form,label:target,law:l.name,caution:l.caution});}});if(steps.length===1)steps.push({form,label:target,law:L("لا توجد قاعدة آلية آمنة في السجل لهذه الصيغة","No safe registered automatic rule changed this form"),caution:L("راجع المعجم والطبعة المتخصصة.","Consult the specialist lexicon and edition.")});state.reconstructionInput=input;state.reconstructionTarget=target;state.reconstructionChain=steps.map(s=>s.form);state.reconstructionResult=`<div class="timeline">${steps.map((s,i)=>`<article class="timeline-item"><time>${escapeHtml(s.label)} · ${i}</time><h3 dir="ltr">${escapeHtml(s.form)}</h3><p>${escapeHtml(s.law)}</p>${s.caution?`<small>${escapeHtml(s.caution)}</small>`:""}</article>`).join("")}</div><div class="academic-note">${L("المخرجات محاكاة قواعد تعليمية وليست اشتقاقًا تاريخيًا نهائيًا؛ البيئات الصوتية والصرفية تحتاج مراجعة بشرية.","Outputs are teaching-rule simulations, not final historical derivations; phonological and morphological environments require expert review.")}</div>`;saveState();render();}
  function playReconstructionChain(){const chain=state.reconstructionChain?.length?state.reconstructionChain:[state.reconstructionInput||"šalāmu"];let i=0;const next=()=>{if(i>=chain.length)return;speak(chain[i++],.65,"ar-SA");setTimeout(next,1400);};next();}
  function synthVowel(){const f1=Number($("#f1")?.value||700),f2=Number($("#f2")?.value||1200),duration=Number($("#duration")?.value||700);try{const C=window.AudioContext||window.webkitAudioContext,ctx=new C(),gain=ctx.createGain();gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.06,ctx.currentTime+.03);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+duration/1000);gain.connect(ctx.destination);[f1,f2].forEach((f,i)=>{const o=ctx.createOscillator();o.type=i?"sine":"triangle";o.frequency.value=f;o.connect(gain);o.start();o.stop(ctx.currentTime+duration/1000);});setTimeout(()=>ctx.close(),duration+150);}catch(_){toast("Audio unavailable");}}
  async function recordAudio(){try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}),rec=new MediaRecorder(stream),chunks=[];rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=()=>{state.lastRecording=Date.now();stream.getTracks().forEach(t=>t.stop());$("#recordingStatus").innerHTML=`<div class="academic-note">${L("تم تسجيل العينة محليًا للمراجعة في هذه الجلسة.","Sample captured locally for review in this session.")}</div>`;};rec.start();$("#recordingStatus").textContent=L("جارٍ التسجيل لمدة 5 ثوانٍ...","Recording for 5 seconds...");drawWave(stream);setTimeout(()=>rec.stop(),5000);}catch(_){toast(L("تعذر الوصول إلى الميكروفون","Microphone unavailable"));}}
  function drawWave(stream){const canvas=$("#waveCanvas");if(!canvas)return;const ctx=canvas.getContext("2d"),AC=window.AudioContext||window.webkitAudioContext,a=new AC(),src=a.createMediaStreamSource(stream),an=a.createAnalyser(),data=new Uint8Array(an.fftSize=512);src.connect(an);function frame(){if(!stream.active){a.close();return;}requestAnimationFrame(frame);an.getByteTimeDomainData(data);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle="#c9953b";ctx.lineWidth=3;ctx.beginPath();data.forEach((v,i)=>{const x=i/data.length*canvas.width,y=v/255*canvas.height;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}frame();}
  function answerQuiz(i){const q=quizQuestions[(state.quizIndex||0)%quizQuestions.length];state.currentQuizAnswer=i;state.quiz.answered++;if(i===q.answer)state.quiz.score+=10;saveState();render();}

