  function typeGlyph(g){const out=$("#keyboardOutput");if(!out)return;const start=out.selectionStart??out.value.length,end=out.selectionEnd??start;out.value=out.value.slice(0,start)+g+out.value.slice(end);out.selectionStart=out.selectionEnd=start+g.length;out.focus();state.keyboardText=out.value;saveState();}
